/* Local minimal jsPDF-compatible image-to-PDF writer for Uti-Mate. */
(function(){'use strict';function enc(s){return new TextEncoder().encode(s)}function b64bin(dataUrl){const b64=String(dataUrl).split(',')[1]||'';const bin=atob(b64);const out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i)&255;return out}function concat(parts){let n=0;for(const p of parts)n+=p.length;const out=new Uint8Array(n);let o=0;for(const p of parts){out.set(p,o);o+=p.length}return out}function pdfBytes(pages){let objs=[null,null];let pageObjNums=[];for(const page of pages){const img=b64bin(page.img);const imgObj=objs.length+1;objs.push([enc('<< /Type /XObject /Subtype /Image /Width '+Math.round(page.w)+' /Height '+Math.round(page.h)+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+img.length+' >>\nstream\n'),img,enc('\nendstream')]);const content='q\n'+page.w+' 0 0 '+page.h+' 0 0 cm\n/Im1 Do\nQ\n';const contObj=objs.length+1;objs.push(enc('<< /Length '+content.length+' >>\nstream\n'+content+'endstream'));const pageObj=objs.length+1;pageObjNums.push(pageObj);objs.push(enc('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+page.w+' '+page.h+'] /Resources << /XObject << /Im1 '+imgObj+' 0 R >> >> /Contents '+contObj+' 0 R >>'));}objs[0]=enc('<< /Type /Catalog /Pages 2 0 R >>');objs[1]=enc('<< /Type /Pages /Count '+pageObjNums.length+' /Kids ['+pageObjNums.map(n=>n+' 0 R').join(' ')+'] >>');let parts=[enc('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n')],offsets=[0];let pos=parts[0].length;for(let i=0;i<objs.length;i++){offsets.push(pos);const head=enc((i+1)+' 0 obj\n');parts.push(head);pos+=head.length;const obj=Array.isArray(objs[i])?concat(objs[i]):objs[i];parts.push(obj);pos+=obj.length;const end=enc('\nendobj\n');parts.push(end);pos+=end.length;}const xref=pos;let xr='xref\n0 '+(objs.length+1)+'\n0000000000 65535 f \n';for(let i=1;i<offsets.length;i++)xr+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';xr+='trailer\n<< /Size '+(objs.length+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';parts.push(enc(xr));return concat(parts)}class jsPDF{constructor(opts){opts=opts||{};this.pages=[];this._format=opts.format||[595,842];this.addPage(this._format)}addPage(format){this._format=format||this._format||[595,842];this.pages.push({w:Number(this._format[0])||595,h:Number(this._format[1])||842,img:null})}addImage(dataUrl,type,x,y,w,h){if(!this.pages.length)this.addPage([w,h]);const p=this.pages[this.pages.length-1];p.img=dataUrl;p.w=Number(w)||p.w;p.h=Number(h)||p.h}save(filename){const usable=this.pages.filter(p=>p.img);const blob=new Blob([pdfBytes(usable)],{type:'application/pdf'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename||'download.pdf';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}}window.jspdf={jsPDF};})();
